INSERT INTO _p VALUES
 ('ENT_ROM_EASTERN_CULTS','PER_ROM_IMPERIAL','NEW HUB (collective). Grouping for the Near-Eastern mystery and solar deities that entered the Roman empire in Roman civic/military dress during the imperial period (1st-4th c. CE): Jupiter Dolichenus, the Heliopolitan triad, Dea Syria, Dea Caelestis, and Sol Invictus Elagabal. Not a single attested deity but an analytic cult-cluster following Beard/North/Price''s treatment of the ''oriental cults''; created to wire these interpretatio-heavy figures together.'),
 ('ENT_ROM_JUPITER_DOLICHENUS','PER_ROM_IMPERIAL','Roman imperial cult of the Baal of Doliche (a city in Commagene, eastern Anatolia), assimilated to Jupiter Optimus Maximus. Depicted standing on a bull, wearing a Phrygian cap, holding a double-axe and thunderbolt. A markedly military god whose cult spread along the limes via the army from the late 1st to mid-3rd c. CE (declining after the sack of Doliche c.253). Underlying figure is the Anatolian/Commagenian storm-god (a Baal-Hadad type) in interpretatio Romana. Attested by dolichena (sanctuaries) and dedications across the Danube, Rhine, and Britain; Beard/North/Price treat it among the oriental cults.'),
 ('ENT_ROM_JUPITER_HELIOPOLITANUS','PER_ROM_IMPERIAL','Chief god of the Heliopolitan triad at Baalbek (Heliopolis, Lebanon): the Romanized Baal/Hadad of Heliopolis assimilated to Jupiter Optimus Maximus. Depicted as a stiff, frontal, cuirassed figure flanked by bulls, holding a whip and ears of grain, with a calathos and busts of the planetary gods. Centre of one of the largest temple complexes of the Roman world. The triad''s two other members are Venus Heliopolitana and Mercury Heliopolitanus. Attested epigraphically at Baalbek and in dedications across the empire; Beard/North/Price discuss the Heliopolitan cult.'),
 ('ENT_ROM_VENUS_HELIOPOLITANA','PER_ROM_IMPERIAL','Female member of the Heliopolitan triad of Baalbek, the Romanized form of the local Syrian goddess (an Atargatis/Astarte type) assimilated to Venus. Consort of Jupiter Heliopolitanus and paired with Mercury Heliopolitanus in the triad. Attested in dedications and iconography (enthroned goddess) from Baalbek and the wider empire; less independently documented than the chief god. Treated within the Heliopolitan cult by Beard/North/Price.'),
 ('ENT_ROM_MERCURY_HELIOPOLITANUS','PER_ROM_IMPERIAL','Third member of the Heliopolitan triad of Baalbek, a youthful god (often read as the divine son of the triad) assimilated to Mercury. Underlying figure is a local Syrian youth-god. Attested epigraphically alongside Jupiter and Venus Heliopolitanus at Baalbek and in scattered dedications; the least independently documented of the triad. Treated within the Heliopolitan cult by Beard/North/Price.'),
 ('ENT_ROM_DEA_SYRIA','PER_ROM_IMPERIAL','The ''Syrian Goddess'' as a cult within Roman religion: the Roman reception of Atargatis of Hierapolis-Bambyce. Her itinerant galli-style priests, ecstatic rites, sacred fish and lions, and processions are described by Lucian (De Dea Syria) and satirized by Apuleius (Metamorphoses 8). Spread through Syrian merchant and slave communities; a temple stood on the Janiculum at Rome. This entity is the Roman cult-form; the underlying deity is the existing ENT_ARA_ATARGATIS, to which it is wired. Beard/North/Price treat Dea Syria among the oriental cults.'),
 ('ENT_ROM_DEA_CAELESTIS','PER_ROM_IMPERIAL','The ''Celestial Goddess'', Roman reception and official form of Carthaginian Tanit (''Tanit face of Baal''), often styled Juno Caelestis. After 146 BCE her cult was Romanized; she became the leading deity of Roman Africa (great temple at Carthage) and was promoted at Rome (notably under Septimius Severus, of African origin, and his dynasty). Associated with the moon, sovereignty, and fertility, sometimes shown riding a lion. This is the Roman cult-form; the underlying deity is the existing ENT_PHO_TANIT, to which it is wired. Discussed by Beard/North/Price.'),
 ('ENT_ROM_SOL_INVICTUS_ELAGABAL','PER_ROM_IMPERIAL','The Emesene sun-god Elagabal in imperial Roman dress as ''Deus Sol Invictus Elagabal''. The emperor Elagabalus (Varius Avitus, r.218-222 CE), hereditary priest of the conical black baetyl of Emesa, brought the stone to Rome, built the Elagaballium on the Palatine, and tried to make Elagabal supreme over the traditional gods; the cult was abolished and the stone returned to Emesa after his murder. This is the short-lived Roman state cult-form; the underlying Syrian deity is the existing ENT_ARA_ELAGABAL (Elagabal of Emesa), and it is distinct from but a precursor to Aurelian''s later ENT_ROM_SOL_INVICTUS. Attested on coinage and by Herodian and the Historia Augusta; Beard/North/Price discuss the episode.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ROM_JUPITER_DOLICHENUS','member_of','ENT_ROM_EASTERN_CULTS','high','Jupiter Dolichenus is one of the Near-Eastern cults in Roman dress grouped under the Eastern-cults hub.'),
 ('ENT_ROM_JUPITER_HELIOPOLITANUS','member_of','ENT_ROM_EASTERN_CULTS','high','Jupiter Heliopolitanus (Baalbek triad) belongs to the Roman Eastern-cults grouping.'),
 ('ENT_ROM_VENUS_HELIOPOLITANA','member_of','ENT_ROM_EASTERN_CULTS','high','Venus Heliopolitana, member of the Baalbek triad, belongs to the Roman Eastern-cults grouping.'),
 ('ENT_ROM_MERCURY_HELIOPOLITANUS','member_of','ENT_ROM_EASTERN_CULTS','high','Mercury Heliopolitanus, member of the Baalbek triad, belongs to the Roman Eastern-cults grouping.'),
 ('ENT_ROM_DEA_SYRIA','member_of','ENT_ROM_EASTERN_CULTS','high','Dea Syria is among the oriental cults of Roman religion in the Eastern-cults grouping.'),
 ('ENT_ROM_DEA_CAELESTIS','member_of','ENT_ROM_EASTERN_CULTS','high','Dea Caelestis is one of the Eastern (African/Punic) cults grouped under the Roman Eastern-cults hub.'),
 ('ENT_ROM_SOL_INVICTUS_ELAGABAL','member_of','ENT_ROM_EASTERN_CULTS','high','Sol Invictus Elagabal, the Emesene solar cult in Roman dress, belongs to the Eastern-cults grouping.'),
 ('ENT_ROM_VENUS_HELIOPOLITANA','consort_of','ENT_ROM_JUPITER_HELIOPOLITANUS','medium','Within the Heliopolitan triad of Baalbek, Venus Heliopolitana is the female consort of the chief god Jupiter Heliopolitanus.'),
 ('ENT_ROM_MERCURY_HELIOPOLITANUS','child_of','ENT_ROM_JUPITER_HELIOPOLITANUS','medium','Mercury Heliopolitanus is generally read as the youthful divine son of the Heliopolitan triad, with Jupiter Heliopolitanus as the father-figure.'),
 ('ENT_ROM_MERCURY_HELIOPOLITANUS','child_of','ENT_ROM_VENUS_HELIOPOLITANA','medium','Mercury Heliopolitanus is read as the divine son of the triad, completing the father-mother-son structure with Venus Heliopolitana as mother.'),
 ('ENT_ROM_JUPITER_DOLICHENUS','cult_form_of','ENT_ROM_JUPITER','high','Jupiter Dolichenus is a Roman cult-epithet/form of Jupiter Optimus Maximus assimilating the Baal of Doliche.'),
 ('ENT_ROM_JUPITER_HELIOPOLITANUS','cult_form_of','ENT_ROM_JUPITER','high','Jupiter Heliopolitanus is the local Baalbek cult-form of Jupiter Optimus Maximus.'),
 ('ENT_ROM_VENUS_HELIOPOLITANA','cult_form_of','ENT_ROM_VENUS','high','Venus Heliopolitana is the Heliopolitan local cult-form of Venus, assimilating the Syrian goddess of Baalbek.'),
 ('ENT_ROM_MERCURY_HELIOPOLITANUS','cult_form_of','ENT_ROM_MERCURY','high','Mercury Heliopolitanus is the Heliopolitan local cult-form of Mercury, assimilating the youthful Syrian son-god.'),
 ('ENT_ROM_DEA_SYRIA','received_as','ENT_ARA_ATARGATIS','high','Dea Syria is the Roman cult reception of the Aramean goddess Atargatis of Hierapolis; Lucian''s De Dea Syria names her so.'),
 ('ENT_ROM_DEA_CAELESTIS','equated_with','ENT_PHO_TANIT','high','Dea/Juno Caelestis is the Romanized interpretatio identification of Carthaginian Tanit, the standard equation.'),
 ('ENT_ROM_DEA_CAELESTIS','received_as','ENT_PHO_TANIT','high','Dea Caelestis is the Roman reception/cult-form of the Punic goddess Tanit after the Romanization of Carthage.'),
 ('ENT_ROM_SOL_INVICTUS_ELAGABAL','received_as','ENT_ARA_ELAGABAL','high','Sol Invictus Elagabal is the Roman imperial cult reception of the Emesene sun-god Elagabal, whose baetyl emperor Elagabalus brought to Rome.'),
 ('ENT_ROM_SOL_INVICTUS_ELAGABAL','aligned_with','ENT_ROM_SOL_INVICTUS','medium','Elagabalus''s short-lived Sol Invictus Elagabal (218-222 CE) is the solar precursor to and shares the Sol Invictus title with Aurelian''s official Sol Invictus (274 CE), though they are distinct cults.'),
 ('ENT_ROM_JUPITER_DOLICHENUS','syncretized_with','ENT_CAN_BAAL','medium','The underlying figure of Jupiter Dolichenus is the Commagenian storm-god of Doliche, a Baal-Hadad type; he is syncretized with the Canaanite/Syrian storm-god Baal Hadad.'),
 ('ENT_ROM_JUPITER_HELIOPOLITANUS','syncretized_with','ENT_CAN_BAAL','medium','Jupiter Heliopolitanus is the Romanized Baal/Hadad of Heliopolis (Baalbek), syncretizing the local Syrian storm-god with Jupiter.'),
 ('ENT_ROM_VENUS_HELIOPOLITANA','syncretized_with','ENT_ARA_ATARGATIS','medium','The female member of the Baalbek triad underlies a local Syrian Atargatis/Astarte-type goddess, syncretized into Venus Heliopolitana.');
